  "bonusChallenge.p.text.2": "依你今天的安排估計，不是館方閉館或領獎截止時間。當剩餘時間不足以走完未到訪場館時，符合條件可追加 1 次答題機會；每趟最多追加一次。",
  "bonusChallenge.label.text": "今天預計離館時間",
  "bonusChallenge.button.text": "儲存時間",
  "bonusChallenge.bonus.fine.print.text": "本趟時間不足的追加機會已發放，修改時間不會再多發。",
  "bonusChallenge.summary.text.2": "機率與保底規則",
