  "bonusChallenge.li.text.4": "每次挑戰需依序答對 3 題，才可抽取 1 次；連續答錯 {value1} 次時改用簡單版本並提供明確提示。",
  "bonusChallenge.li.text.5": "每次抽取保證取得 1 片尚未收集的拼圖，最多抽取 {value1} 次；不保證每個人當天能集滿，未完成可保留進度。",
  "bonusChallenge.li.text.6": "全部免費，不開放付費購買次數；此處不會預留庫存、核發正式領獎資格或清除到訪紀錄。",
