  "museumQuestions.copy.office.evidenceLocator.copy": "正文191–194行",
  "museumQuestions.copy.office.verification.copy": "已重新開啟官方建築介紹正文；內容為歷史用途與建築說明，非當日開放公告。",
  "museumQuestions.copy.assembly.factScope.copy": "檢修需求形成大跨距；大面積玻璃窗供採光；組立工場太子樓以通風為主。",
  "museumQuestions.copy.assembly.evidenceLocator.copy": "正文195、200、204行",
  "museumQuestions.copy.forging.factScope.copy": "熱鍛造先加熱再施壓；大鍛件以蒸汽鎚或空氣鎚成形；靠近原動室減少能源散逸。",
  "museumQuestions.copy.forging.evidenceLocator.copy": "正文203、208行",
  "museumQuestions.copy.diesel.factScope.copy": "因應動力柴油化興建；共構建築中間最高為柴電工場；屋頂太子樓兼顧採光與通風。",
  "museumQuestions.copy.diesel.evidenceLocator.copy": "正文183、191行",
  "museumQuestions.copy.coach.factScope.copy": "蝴蝶屋頂連棟群同時包含客車與貨車等工場；曾進行木造客車鋼體化。",
  "museumQuestions.copy.coach.evidenceLocator.copy": "正文181、185行",
  "museumQuestions.copy.power.factScope.copy": "供應蒸汽、壓縮空氣並分送外部電力；壓縮空氣用於氣動工具；柴油發電機為緊急用途。",
  "museumQuestions.copy.power.evidenceLocator.copy": "正文191、199行",
  "museumQuestions.copy.traverser.factScope.copy": "平台平移銜接不同股道；導電柱接架空電線驅動馬達；絞盤與鋼索拉車上平台。",
  "museumQuestions.copy.traverser.evidenceLocator.copy": "正文179、185、193、195行",
  "museumQuestions.copy.training.factScope.copy": "培育車輛維修人才；原木造所因柴油電氣機車維修中心興建而遷建；新所為兩層鋼筋混凝土建築。",
  "museumQuestions.copy.training.evidenceLocator.copy": "正文183行",
  "museumQuestions.copy.bath.factScope.copy": "為職工洗去工作油污的福利設施；熱水由原動室蒸汽加熱；泡澡前先在水槽旁洗淨。",
  "museumQuestions.copy.bath.evidenceLocator.copy": "正文179、189行",
