  "familyPage.copy.28": "已記錄這位成員的同意；符合共同同意條件時才會清除同行紀錄。",
  "familyPage.copy.29": "操作未完成，紀錄沒有清除，請查看頁面提示。",
  "groupModel.copy.copy": "請先建立同行組別。",
  "groupModel.copy.copy.2": "這組已有兩人，不能加入第三人。",
  "groupModel.copy.copy.3": "已完成第 6 站起停止新加入；既有成員可重連。",
  "groupModel.copy.group.members.role.copy": "建組者",
  "groupModel.copy.group.members.role.copy.2": "同行者",
  "onboardingDialog.copy.title.copy": "跟著站序，開始探索",
  "onboardingDialog.copy.description.copy": "點「園區探索地圖」找站點，點「探索旅程」回看進度；圖片上的按鈕能閱讀展區故事。",
  "onboardingDialog.copy.note.copy": "進入探索後，可用入口下方的「操作說明」再看一次。路線僅供參考，參觀依現場開放範圍。",
  "onboardingDialog.copy.title.copy.2": "一站一片，一起收集",
  "onboardingDialog.copy.description.copy.2": "1～2 人共享首輪 10 塊拼圖；到站完成確認後，收集這一站的拼圖。",
  "onboardingDialog.copy.note.copy.2": "掃描站點碼領片，紀錄僅存於此裝置，不驗證現場位置。",
  "onboardingDialog.copy.title.copy.3": "留下合照，也能輕鬆略過",
  "onboardingDialog.copy.description.copy.3": "拍照是自選，不影響領片；合照可留作這趟旅程的紀念。",
  "onboardingDialog.copy.note.copy.3": "到站後可自選合照或拍照，儲存到本機紀念照區。",
  "onboardingDialog.guide.graphic.label.text": "路線圖解",
  "onboardingDialog.guide.route.nodes.name.copy": "起點",
  "onboardingDialog.guide.route.nodes.name.copy.2": "依序",
  "onboardingDialog.guide.route.nodes.name.copy.3": "終點",
  "onboardingDialog.p.text": "每站依固定順序解鎖，順暢走訪全區",
  "onboardingDialog.guide.graphic.label.text.2": "票根免登入",
  "onboardingDialog.strong.text": "1～2人",
  "onboardingDialog.span.text": "首輪 10 片拼圖",
  "onboardingDialog.p.text.2": "1～2 人共享首輪 10 塊拼圖・圖解",
  "onboardingDialog.strong.text.2": "自選合照卡",
  "onboardingDialog.strong.text.3": "紀念照典藏",
  "onboardingDialog.p.text.3": "可從右上角選單的「旅程服務與玩法說明」重看新手說明。",
  "onboardingDialog.span.text.2": "新手說明",
  "onboardingDialog.button.aria.label": "略過新手說明",
  "onboardingDialog.intro.storage.notice.text": "目前僅本次有效，無法保證下次記住啟動狀態；仍可繼續使用。",
  "onboardingDialog.guide.previous.text": "上一步",
  "onboardingDialog.copy": "完成說明",
  "onboardingDialog.copy.2": "下一步",
  "welcomeScreen.welcome.start.background.aria.label": "點擊背景開始旅程",
  "welcomeScreen.welcome.slogan.text": "把沿途的發現，拼成一段回憶",
  "welcomeScreen.welcome.keyboard.hint.text": "點擊畫面或按任意鍵開始",
  "welcomeScreen.sr.only.text": "Tab 可移動焦點；Escape 與系統快捷鍵不會開始旅程。",
  "morePage.copy.title.copy": "查看官方最新消息",
  "morePage.copy.description.copy": "園區公告、展覽活動與服務異動",
  "morePage.copy.title.copy.2": "國家鐵道博物館官方網站",
  "morePage.copy.description.copy.2": "認識鐵博，查看官方展覽與服務",
  "morePage.copy.title.copy.3": "參觀資訊",
  "morePage.copy.description.copy.3": "查看官方園區資訊與參觀服務",
  "morePage.copy.title.copy.4": "交通指南",
  "morePage.copy.description.copy.4": "查看官方交通與周邊停車資訊",
  "morePage.heading.description.text": "登入、親子同行與玩法說明，都在這裡。",
  "morePage.more.explore.eyebrow.text": "探索任務",
  "morePage.more.explore.title.text": "一站一片，開始你的鐵道旅程",
  "morePage.p.text": "先看今日路線與下一站，再體驗探索任務。",
  "morePage.more.explore.action.text": "前往探索任務",
  "morePage.p.text.2": "票根免登入，也可以選擇單人或雙人同行。",
  "morePage.button.text": "登入／同行",
  "morePage.more.services.title.text": "玩法與旅程",
  "morePage.small.text": "從頭認識探索、集片與合照玩法",
  "morePage.strong.text": "重看歡迎畫面",
  "morePage.small.text.2": "再看一次這趟旅程的開場",
  "morePage.small.text.3": "查看拼圖與旅程紀念品",
  "morePage.small.text.4": "合照自由選擇，不影響集片",
  "morePage.span.text": "玩法說明",
  "morePage.p.text.3": "首輪依動線到站收集拼圖，也可在「我的拼圖」參加答題補收。集滿整套 10 片後查看兌換選項；收藏不等於實際到訪。",
  "morePage.p.text.4": "儲存合照是選擇性步驟；不拍照，也不影響集片。第二輪才開放自由踩點。",
  "morePage.p.text.5": "可從第 01 站依序體驗十站掃碼與領片，並將自選合照或照片儲存在這個瀏覽器的紀念照區；不會上傳雲端。",
  "morePage.more.official.title.text": "官方資訊",
  "morePage.span.text.2": "外部連結",
  "morePage.more.section.note.text": "以下連結會在新分頁開啟官方網站。園區消息與參觀安排，請以館方最新公告為準。",
  "morePage.more.external.caption.text": "官方網站・新分頁開啟",
  "morePage.more.source.note.text": "這裡提供官方消息入口，不會自動同步或代替館方公告。",
  "familyPhotoGallery.copy.copy.copy": "旅程的起點，和你一起留下。",
  "familyPhotoGallery.copy.alt.copy": "成年照顧者與學齡孩子在鐵道建築前合照",
  "familyPhotoGallery.copy.copy.copy.2": "一起發現火車，也記住彼此的笑容。",
  "familyPhotoGallery.copy.alt.copy.2": "成年照顧者與學齡孩子在蒸汽機車旁合照",
  "familyPhotoGallery.copy.copy.copy.3": "車廂裡的合照，把今天收藏起來。",
  "familyPhotoGallery.copy.alt.copy.3": "成年照顧者與學齡孩子坐在車廂內合照",
  "familyPhotoGallery.eyebrow.text": "一起走過的每個片刻",
  "familyPhotoGallery.family.gallery.title.text": "親子旅程合照",
  "familyPhotoGallery.p.text": "看看你們想留下哪個片刻。合照不會自動加入相冊或到站紀錄。",
  "familyPhotoGallery.small.text": "親子合照",
  "photoServicePage.copy.copy": "排版目前只保留於這次開啟，請先下載預覽圖。",
