  "museumQuestions.copy.office.publisher.copy": "國家鐵道博物館",
  "museumQuestions.copy.office.factScope.copy": "Former depot administrative centre; floors built separately, with Art Deco below and modernism above.",
  "museumQuestions.copy.office.evidenceLocator.copy": "Main text, lines 191–194",
  "museumQuestions.copy.office.verification.copy": "Official building article reviewed again; historical use and architecture, not today's opening notice.",
  "museumQuestions.copy.assembly.factScope.copy": "Wide spans for repairs, large daylight windows and a raised roof mainly for ventilation.",
  "museumQuestions.copy.assembly.evidenceLocator.copy": "Main text, lines 195, 200, 204",
  "museumQuestions.copy.forging.factScope.copy": "Hot forging heats then presses; large parts use steam or air hammers; proximity to power reduces losses.",
  "museumQuestions.copy.forging.evidenceLocator.copy": "Main text, lines 203, 208",
  "museumQuestions.copy.diesel.factScope.copy": "Built for dieselisation; tallest central workshop; raised roof for daylight and ventilation.",
  "museumQuestions.copy.diesel.evidenceLocator.copy": "Main text, lines 183, 191",
  "museumQuestions.copy.coach.factScope.copy": "Butterfly-roof complex with passenger and freight workshops; wooden carriage steel-body conversions.",
  "museumQuestions.copy.coach.evidenceLocator.copy": "Main text, lines 181, 185",
  "museumQuestions.copy.power.factScope.copy": "Steam and compressed air supply and external power distribution; air for pneumatic tools; diesel generator for emergencies.",
  "museumQuestions.copy.power.evidenceLocator.copy": "Main text, lines 191, 199",
  "museumQuestions.copy.traverser.factScope.copy": "Platform moves sideways between tracks; overhead contact pole powers motor; winch and cable pull vehicles aboard.",
  "museumQuestions.copy.traverser.evidenceLocator.copy": "Main text, lines 179, 185, 193, 195",
  "museumQuestions.copy.training.factScope.copy": "Vehicle maintenance training; wooden school relocated for diesel-electric repairs; new two-storey concrete building.",
  "museumQuestions.copy.training.evidenceLocator.copy": "Main text, line 183",
  "museumQuestions.copy.bath.factScope.copy": "Employee welfare for washing off oil; steam-heated water; wash by the trough before bathing.",
  "museumQuestions.copy.bath.evidenceLocator.copy": "Main text, lines 179, 189",
  "museumQuestions.copy.hall.factScope.copy": "Formal name 文康中心; dining, assembly, badminton, table tennis and billiards.",
  "museumQuestions.copy.hall.evidenceLocator.copy": "Main text, line 187",
  "museumQuestions.copy.title.copy": "What work was mainly done at 總辦公室?",
  "museumQuestions.copy.choices.copy": "Administration, including personnel and accounting",
  "museumQuestions.copy.choices.copy.2": "Machining wheels and axles",
  "museumQuestions.copy.hint.copy": "This was the depot's administrative centre, handling personnel, accounting and similar work.",
  "museumQuestions.copy.easyTitle.copy": "Hint: this was the administrative centre. What work belonged here?",
  "museumQuestions.copy.easyChoices.copy": "Personnel and accounting",
  "museumQuestions.copy.easyChoices.copy.2": "Wheel machining",
  "museumQuestions.copy.title.copy.2": "Why do the two floors of 總辦公室 have different styles?",
  "museumQuestions.copy.choices.copy.3": "They were built together with styles chosen for different uses",
  "museumQuestions.copy.choices.copy.4": "They were built in different eras",
  "museumQuestions.copy.hint.copy.2": "The first floor was completed earlier; the second was added later, preserving two eras' styles.",
  "museumQuestions.copy.easyTitle.copy.2": "Hint: the second floor was added later. Were the floors built at the same time?",
  "museumQuestions.copy.easyChoices.copy.3": "Both built at the same time",
  "museumQuestions.copy.easyChoices.copy.4": "Built in different periods",
  "museumQuestions.copy.title.copy.3": "Which style does the official introduction identify on the first floor?",
  "museumQuestions.copy.choices.copy.5": "Art Deco with decorative lines",
  "museumQuestions.copy.choices.copy.6": "Simple, practical modernism",
  "museumQuestions.copy.hint.copy.3": "The first floor has wall decorations and ornamental arches; the second is simpler and more practical.",
  "museumQuestions.copy.easyTitle.copy.3": "Hint: wall decorations and ornamental arches. Which style fits?",
  "museumQuestions.copy.easyChoices.copy.5": "Art Deco",
  "museumQuestions.copy.easyChoices.copy.6": "Simple modernism",
  "museumQuestions.copy.title.copy.4": "Why did 組立工場 need a wide-span space?",
  "museumQuestions.copy.choices.copy.7": "To bring administrative desks and offices together",
  "museumQuestions.copy.choices.copy.8": "To accommodate vehicle repairs, lifting and machinery",
  "museumQuestions.copy.hint.copy.4": "The building had to fit vehicles, lifting heights and repair equipment.",
  "museumQuestions.copy.easyTitle.copy.4": "Hint: trains came inside for repairs. What did the space need to fit?",
  "museumQuestions.copy.easyChoices.copy.7": "Administrative desks",
  "museumQuestions.copy.easyChoices.copy.8": "Vehicles and repair equipment",
  "museumQuestions.copy.title.copy.5": "What was an important purpose of the workshop's large glass windows?",
  "museumQuestions.copy.choices.copy.9": "Bring in daylight for repair work",
  "museumQuestions.copy.choices.copy.10": "Mainly separate repair bays",
  "museumQuestions.copy.hint.copy.5": "Large windows lit the work area and helped reduce lighting energy use.",
  "museumQuestions.copy.easyTitle.copy.5": "Hint: glass windows let daylight in. What did they improve?",
  "museumQuestions.copy.easyChoices.copy.9": "Workplace lighting",
  "museumQuestions.copy.easyChoices.copy.10": "Separation of work bays",
  "museumQuestions.copy.title.copy.6": "What was the main role of 組立工場's raised roof section?",
  "museumQuestions.copy.choices.copy.11": "Parts storage",
  "museumQuestions.copy.choices.copy.12": "Workshop ventilation",
  "museumQuestions.copy.hint.copy.6": "Large windows already provided daylight; the roof section's louvres mainly served ventilation.",
  "museumQuestions.copy.easyTitle.copy.6": "Hint: the roof section has louvres. What should flow through them?",
  "museumQuestions.copy.easyChoices.copy.11": "Store parts",
  "museumQuestions.copy.easyChoices.copy.12": "Air inside the workshop",
  "museumQuestions.copy.title.copy.7": "How did hot forging shape metal at 鍛冶工場?",
  "museumQuestions.copy.choices.copy.13": "Heat it, then hammer it under pressure",
  "museumQuestions.copy.choices.copy.14": "Pour molten metal into a mould",
  "museumQuestions.copy.hint.copy.7": "Hot forging first softens metal with heat, then changes its shape with pressure.",
  "museumQuestions.copy.easyTitle.copy.7": "Hint: heat first, then apply force. What comes next?",
  "museumQuestions.copy.easyChoices.copy.13": "Hammer into shape",
  "museumQuestions.copy.easyChoices.copy.14": "Pour into a mould",
  "museumQuestions.copy.title.copy.8": "Which equipment mainly shaped large forgings?",
  "museumQuestions.copy.choices.copy.15": "Continuous cutting on a lathe",
  "museumQuestions.copy.choices.copy.16": "Pressure from a steam or air hammer",
