  "stationCulture.copy.office.label.copy": "Museum source | 總辦公室",
  "stationCulture.copy.assembly.label.copy": "Museum source | 組立工場",
  "stationCulture.copy.forging.label.copy": "Museum source | 鍛冶工場",
