  "bonusChallenge.h3.text": "퍼즐을 모두 모았어요",
  "bonusChallenge.p.text": "뽑기 기회를 더 사용하지 않아요. 방문은 순서대로 계속할 수 있어요.",
  "bonusChallenge.a.text": "교환소 보기",
  "bonusChallenge.span.text.4": "최근 수집: {value1}. 퍼즐에 추가했으며 방문 기록은 그대로예요.",
  "bonusChallenge.summary.text": "시간이 부족한가요? 나갈 시간 설정",
  "bonusChallenge.p.text.2": "폐관이나 수령 마감이 아닌 자신의 일정을 기준으로 해요. 남은 지점을 돌 시간이 부족하면 조건에 따라 여정당 한 번만 기회를 추가해요.",
  "bonusChallenge.label.text": "오늘 나갈 예정 시간",
  "bonusChallenge.button.text": "시간 저장",
  "bonusChallenge.bonus.fine.print.text": "이번 여정의 시간 추가 기회는 이미 받았어요. 시간을 바꿔도 더 지급하지 않아요.",
  "bonusChallenge.summary.text.2": "확률과 보장 규칙",
  "bonusChallenge.li.text": "지정 방문 수마다 한 번 확인해요:",
  "bonusChallenge.li.message": "{value1}곳 방문: {value2}%",
  "bonusChallenge.li.text.2": ". 100% 지점에서는 퀴즈 기회를 보장해요.",
  "bonusChallenge.li.text.3": "일반 기회는 최대 {value1}회예요. 출발 전 {value2}분 이내에 남은 경로를 마치기 어려우면 최대 1회를 추가해요. 미방문 지점당 {value3}분은 예상치이며 보장 시간이 아니에요.",
  "bonusChallenge.li.text.4": "세 문제를 순서대로 맞히면 한 번 뽑아요. {value1}회 연속 틀리면 쉬운 문제와 힌트를 제공해요.",
  "bonusChallenge.li.text.5": "매번 없는 조각 1개를 받으며 최대 {value1}회 뽑아요. 당일 완성은 보장하지 않으며 미완료 진행은 보관할 수 있어요.",
  "bonusChallenge.li.text.6": "모두 무료이며 횟수를 구매할 수 없어요. 재고 예약이나 공식 수령 자격을 발급하지 않으며 방문 기록도 지우지 않아요.",
  "bonusChallenge.copy": "계속 탐험해요. {value1}곳째에 기회를 확인해요.",
  "bonusChallenge.copy.2": "창에서 이전 문제를 이어가요. 맞힌 진행은 유지돼요.",
  "bonusChallenge.copy.3": "세 문제를 마쳤어요. 창을 열어 퍼즐을 받아요.",
  "bonusChallenge.copy.4": "창을 열고 답을 고른 뒤 확인해 주세요.",
  "bonusChallenge.copy.5": "규칙에 따라 기회를 지급해요. 새로고침해도 다시 지급하지 않아요.",
  "bonusChallenge.copy.6": "{value1}로 설정했어요. 이 기기의 날짜와 시간을 기준으로 해요.",
  "bonusChallenge.copy.7": "오늘 중 현재보다 늦은 시간을 골라 주세요. 자동으로 내일로 바꾸지 않아요.",
  "bonusDialog.copy.message": "힌트를 살펴보세요: {value1}",
  "bonusDialog.bonus.popup.steps.aria.label": "세 문제 도전 진행",
  "bonusDialog.bonus.popup.kicker.text": "{value1} · {value2}/{value3}번 문제{value4}",
  "bonusDialog.bonus.popup.options.aria.label": "답 하나 선택",
  "bonusDialog.bonus.popup.primary.text": "답 확인",
  "bonusDialog.p.text": "자료 출처",
  "bonusDialog.copy.copy": "이전 이용 규칙 퀴즈를 이어가요. 다음 도전에는 박물관 지식 문제를 사용해요.",
  "bonusDialog.copy.copy.2": "박물관 공개 자료를 바탕으로 만들었으며 공식 승인 문제는 아니에요.",
  "bonusDialog.copy.copy.3": "퍼즐은 이 기기에만 기록하며 공식 수령 자격을 뜻하지 않아요.",
  "bonusDialog.copy.copy.4": "뽑기 결과를 확인할 수 없어요. 퍼즐을 확인해 주세요. 자동으로 다시 뽑지 않아요.",
  "bonusDialog.eyebrow.text": "철도 여행 · 추가 퍼즐",
  "bonusDialog.bonus.popup.close.aria.label": "퀴즈와 뽑기 창 닫기",
  "bonusDialog.bonus.popup.kicker.text.2": "세 문제 정답 · 한 번 뽑기",
  "bonusDialog.h3.text": "여행에 새 이야기를 더해요.",
  "bonusDialog.p.text.2": "매번 없는 조각 1개를 받아요. 수집만 늘어나며 실제 방문 기록은 그대로예요.",
  "bonusDialog.bonus.popup.primary.text.2": "퍼즐 뽑기",
