  "bonusDialog.strong.message": "{value1}번 퍼즐 조각",
  "bonusDialog.small.text": "퀴즈 수집 · 실제 방문 아님",
  "bonusDialog.bonus.popup.primary.text.3": "내 퍼즐 보기",
  "bonusDialog.bonus.popup.secondary.text": "탐험 계속",
  "bonusDialog.h3.text.3": "진행 상황 갱신",
  "bonusDialog.p.text.3": "진행 중인 도전이나 대기 중인 뽑기가 없어요. 내 퍼즐을 확인해 주세요.",
  "bonusDialog.bonus.popup.storage.warning.text": "저장할 수 없어요. 페이지를 닫으면 이번 진행이 사라질 수 있어요.",
  "bonusDialog.span.text": "퀴즈 규칙",
  "bonusDialog.strong.text": "도전 방법:",
  "bonusDialog.li.text": "답을 고르고 확인해요. 세 문제를 순서대로 맞히면 한 번 뽑아요.",
  "bonusDialog.strong.text.2": "틀렸다면:",
  "bonusDialog.li.text.2": "힌트를 보고 다시 시도해요. {value1}회 연속 틀리면 쉬운 문제로 바꿔요. 퍼즐을 차감하거나 뽑기 횟수를 늘리지 않아요.",
