  "bonusStore.copy.storageMessage.copy": "저장할 수 없어요. 추가 퍼즐·문제·뽑기는 이번에만 유지하며 페이지를 닫으면 사라질 수 있어요.",
  "bonusStore.copy.message.copy": "추가 퀴즈와 뽑기를 초기화했어요. 방문 기록은 탐험에서 따로 관리해요.",
  "bonusStore.copy.message.copy.2": "추가 퍼즐 진행을 갱신했어요.",
  "museumQuestions.copy.office.publisher.copy": "國家鐵道博物館",
  "museumQuestions.copy.office.factScope.copy": "옛 공장 행정 중심. 두 층은 시기가 다르며 1층은 아르데코, 2층은 모더니즘이에요.",
  "museumQuestions.copy.office.evidenceLocator.copy": "본문 191~194행",
  "museumQuestions.copy.office.verification.copy": "공식 건축 소개를 다시 확인했어요. 역사적 용도와 건축 설명이며 당일 개방 공지는 아니에요.",
  "museumQuestions.copy.assembly.factScope.copy": "정비용 넓은 공간, 채광용 큰 창, 주로 환기용인 높은 지붕.",
  "museumQuestions.copy.assembly.evidenceLocator.copy": "본문 195·200·204행",
  "museumQuestions.copy.forging.factScope.copy": "열간 단조는 가열 후 가압해요. 큰 부품은 증기·공기 해머로 만들며 동력실 가까이에 두어 손실을 줄여요.",
  "museumQuestions.copy.forging.evidenceLocator.copy": "본문 203·208행",
  "museumQuestions.copy.diesel.factScope.copy": "디젤화에 맞춰 건설. 중앙 공장이 가장 높고 지붕으로 채광과 환기를 확보해요.",
  "museumQuestions.copy.diesel.evidenceLocator.copy": "본문 183·191행",
  "museumQuestions.copy.coach.factScope.copy": "나비 지붕 건물군에 객차·화차 공장이 있고 목조 객차 강철 차체화도 했어요.",
  "museumQuestions.copy.coach.evidenceLocator.copy": "본문 181·185행",
  "museumQuestions.copy.power.factScope.copy": "증기·압축 공기 공급과 외부 전기 분배. 공압 공구용 공기, 비상용 디젤 발전기.",
  "museumQuestions.copy.power.evidenceLocator.copy": "본문 191·199행",
  "museumQuestions.copy.traverser.factScope.copy": "플랫폼이 평행 이동해 선로를 연결해요. 가공 전선으로 모터를 구동하고 윈치와 케이블로 차량을 끌어요.",
  "museumQuestions.copy.traverser.evidenceLocator.copy": "본문 179·185·193·195행",
  "museumQuestions.copy.training.factScope.copy": "차량 정비 인력 양성. 디젤 전기 정비시설 때문에 목조 학교를 옮겨 2층 철근 콘크리트 건물을 지었어요.",
  "museumQuestions.copy.training.evidenceLocator.copy": "본문 183행",
  "museumQuestions.copy.bath.factScope.copy": "직원 기름때를 씻는 복지시설. 증기로 물을 데우며 입욕 전 수조 옆에서 씻었어요.",
  "museumQuestions.copy.bath.evidenceLocator.copy": "본문 179·189행",
  "museumQuestions.copy.hall.factScope.copy": "정식 명칭 文康中心. 식사·모임·배드민턴·탁구·당구 용도.",
  "museumQuestions.copy.hall.evidenceLocator.copy": "본문 187행",
