  "familyPage.copy.16": "두 번째 멤버가 이 기기 여정에 참여해 기존 진행을 공유해요.",
  "familyPage.copy.17": "역할에서 나왔어요. 멤버와 진행은 유지하며 그룹 변경은 아직 지원하지 않아요.",
