  "familyPage.copy.26": "다시 확인해 주세요. 아직 지우지 않았어요.",
  "familyPage.copy.27": "초기화를 요청했어요. 다른 멤버의 동의를 기다리며 아직 지우지 않았어요.",
  "familyPage.copy.28": "이 멤버의 동의를 기록했어요. 필요한 멤버가 모두 동의해야 동행 기록을 지워요.",
