  "onboardingDialog.copy.note.copy.2": "지점 코드를 스캔해 퍼즐을 받아요. 이 기기에만 기록하며 현장 위치는 확인하지 않아요.",
  "onboardingDialog.copy.title.copy.3": "사진을 남겨도, 건너뛰어도 좋아요",
  "onboardingDialog.copy.description.copy.3": "사진은 선택이며 퍼즐 수령에 영향이 없어요. 여행의 추억으로 남겨요.",
  "onboardingDialog.copy.note.copy.3": "도착 후 사진을 고르거나 예시 사진을 기기에 저장할 수 있어요. 예시 사진은 참고용이에요.",
