  "photoServicePage.copy.copy": "편집본은 이번에만 유지돼요. 먼저 미리 보기를 다운로드해 주세요.",
  "photoServicePage.copy.copy.2": "두 장 형식에는 최대 두 장만 선택해요. 먼저 한 장을 해제해 주세요.",
  "photoServicePage.copy.copy.3": "편집 중이거나 사진이 부족해요. 선택과 미리 보기를 먼저 마쳐 주세요.",
  "photoServicePage.copy.copy.4": "예약 예시를 저장했어요. 결제나 인쇄는 하지 않았어요. 아래에서 수령 정보를 볼 수 있어요.",
  "photoServicePage.copy.copy.5": "예약 예시를 취소하고 자리를 비웠어요. 실제 환불은 하지 않았어요.",
