  "redemptionOperations.p.text.6": "¾는 표시 기준이에요. 전체 {value1}종 중 최소 {value2}종을 보여야 하며 ¾가 재고 있다는 뜻은 아니에요. 추가 구매 없는 상품도 표시하며 비용과 수량은 확인 중이에요.",
