  "redemptionRulesDialog.p.text.3": "온라인 결제·상품 예약·현장 확인은 아직 지원하지 않아요. 퍼즐 수집은 유지돼요.",
  "redemptionRulesDialog.p.text.4": "방문과 퀴즈로 퍼즐을 모아요. 완성이 모든 곳의 실제 방문을 뜻하지 않아요.",
  "redemptionRulesDialog.p.text.5": "품목·재고·보관 기한은 확인 중이에요. 2차는 자유 방문이지만 시작·교환 규칙은 미정이에요. 재방문 상품은 전시용이며 2차 퍼즐이나 수령 자격을 지급하지 않아요.",
