  "redemptionCatalog.copy.priceNote.copy": "가격은 확인 중이에요.",
  "redemptionModel.copy.copy": "1차 한 세트당 한 번 등록해요. 미완료는 취소 후 다시 고르지만 완료 후 중복 생성은 안 돼요. 결제·차감·상품 예약은 없어요.",
  "redemptionModel.copy.message.copy": "수령 기록을 확인할 수 없어요. 자료를 보관하고 확인해 주세요. 다시 발급하지 않아요.",
  "redemptionModel.copy.message.copy.2": "이 퍼즐의 등록은 완료됐어요. 수집은 유지하며 중복 등록할 수 없어요.",
