  "redemptionModel.copy.copy.16": "등록을 취소했어요. 퍼즐을 유지하며 기념품을 다시 고를 수 있어요.",
  "redemptionModel.copy.storageMessage.copy": "저장할 수 없어 등록은 이번에만 유지돼요.",
