  "redemptionOperationsModel.copy.copy.11": "품절이에요. 기존 등록을 취소하고 대안을 직접 골라 주세요. 추가 금액은 다시 확인해요.",
  "redemptionOperationsModel.copy.copy.12": "품절이며 추가 금액이 같거나 낮은 대안이 없어요. 수집과 기존 기록은 유지돼요.",
  "redemptionOperationsModel.copy.message.copy": "설정을 저장하지 않았어요. 같은 날 30분 초과 운영하며 ¾ 품목과 추가 구매 없는 상품 하나를 표시해야 해요.",
  "redemptionOperationsModel.copy.message.copy.2": "서비스 설정을 바꿨어요. 퍼즐과 기존 기록은 그대로예요.",
